SELECT 
FROM jn_inventory
WHERE material_id = #{materialId}
AND wh_id = #{whId}

    AND batch_no = #{batchNo}


    AND (batch_no IS NULL OR batch_no = '')

LIMIT 1

mapper.update:
UPDATE jn_inventory
SET quantity = quantity + #{qty},
    available_qty = available_qty + #{qty},
    update_time = NOW()
WHERE material_id = #{materialId}
AND wh_id = #{whId}

    AND batch_no = #{batchNo}

AND quantity + #{qty} >= 0

UPDATE jn_inventory
SET quantity = quantity - #{qty},
    available_qty = available_qty - #{qty},
    update_time = NOW()
WHERE material_id = #{materialId}
AND wh_id = #{whId}

    AND batch_no = #{batchNo}

AND available_qty >= #{qty}
